		     /*saveMasterMdCtNewCustomerBidStatus*/
                   UPDATE KEP_CUSTOMER_RFQ
                   SET  PROCESS_TYPE = #{st_process_type}
                     , CHANGE_USER_ID =#{USER_ID}
                     , CHANGE_DATE =SYSDATE           
                 WHERE BUYER =#{st_com_code}
                 AND REVISION=#{st_revision}


		     /*saveMasterMdCtNewCustomerBidList*/
                 UPDATE KEP_CUSTOMER_RFQ B
                   SET B.RFQ_TYPE = #{st_rfq_type}
					 ,B.RFQ_RECEIPT_DATE = #{st_rfq_r_date}
					 ,B.RFQ_AMOUNT_NOTE = #{st_rfq_amount}
					 ,B.RFQ_CLOSE_DATE = #{st_rfq_c_date}
					 ,B.MRO_OPEN_DATE = #{st_mro_open_date}
					 ,B.MRO_COMPANY = #{st_mro_cmpy}
					 ,B.RFQ_COMPANY = #{st_rfq_cmpy}
					 ,B.EVALUATION_NOTE = #{st_eval_note}
					 ,B.RFQ_KEP_DEPT = #{st_rfq_dept_code}
					 ,B.RFQ_KEP_S_USER_ID = #{st_kep_s_user_id}
					 ,B.RFQ_KEP_B_USER_ID = #{st_kep_b_user_id}
					 ,B.SC_BASICS_PRICE_YN = #{st_price_yn}
					 ,B.SC_QTY_YN = #{st_sc_qty_yn}
					 ,B.SC_ORDER_FREQUENCY_YN = #{st_sc_order_yn}
					 ,B.SC_EXISTING_SELLER_FLAG = #{st_sc_seller_yn}
					 ,B.SC_DESCRIPTION_YN = #{st_desc_yn}
					 ,B.SC_SPECIFICATION_YN = #{st_spec_yn}
					 ,B.SC_MAKER_YN = #{st_maker_yn}
					 ,B.SC_ORIGIN_YN = #{st_orgin_yn}
					 ,B.SC_MEASURE_YN = #{st_measure_yn}
					 ,B.SC_DELIVERY_TYPE = #{st_delivery_yn}
					 ,B.SC_EXISTING_SELLER_RFQ_FLAG = #{st_seller_rfq_yn}
					 ,B.SC_BUYER_OPEN_YN = #{st_buyer_open_yn}
					 ,B.SC_LOANER_PROPOSAL_YN = #{st_proposal_yn}
					 ,B.SC_SAMPLE_YN = #{st_sample_yn}
					 ,B.SC_MARKET_CONDITIONS_YN = #{st_cond_yn}
					 ,B.SC_CONTRACT_PERIOD_TYPE = #{st_period_yn}
					 ,B.SC_NEW_ITEM_RATE_TYPE = #{st_new_rate}
					 ,B.SC_BILL_TYPE = #{st_bill_type}
					 ,B.SC_ADD_DATE=SYSDATE
					 ,B.SC_ADD_USER_ID = #{USER_ID}
					 ,B.CHANGE_DATE = SYSDATE
					 ,B.CHANGE_USER_ID = #{USER_ID}
					 ,B.BID_COMPANY = #{st_bid_company}
					 ,B.BID_NOTE = #{st_bid_note}
					 ,B.BID_IMAGE_KEY = #{st_image_key}
					 ,B.BID_ADD_DATE = SYSDATE
					 ,B.BID_ADD_USER_ID = #{USER_ID}
					 ,B.SC_NOTE = #{st_sc_note}
                 WHERE BUYER =#{st_com_code}
                 AND REVISION=#{st_revision}


		     /*saveMasterMdCtNewCustomerSetList*/
                 UPDATE KEP_CUSTOMER_RFQ B
                   SET B.SETUP_NOTE = #{st_setup_note}
					 ,B.SETUP_IMAGE_KEY = #{st_image_key}
					 ,B.SETUP_ADD_DATE = SYSDATE
					 ,B.SETUP_ADD_USER_ID = #{USER_ID}
                 WHERE BUYER =#{st_com_code}
                 AND REVISION=#{st_revision}


		     /*cancleMasterMdCtNewCustomerSetList*/
                 UPDATE KEP_CUSTOMER_RFQ B
                   SET B.PROCESS_TYPE = 'ST' 
                     ,  B.SETUP_NOTE = ''
					 ,B.SETUP_IMAGE_KEY = ''
					 ,B.SETUP_ADD_DATE = NULL
					 ,B.SETUP_ADD_USER_ID = ''
                 WHERE BUYER =#{st_com_code}
                 AND REVISION=#{st_revision}


		     /*saveMasterMdCtNewCustomerConList*/
                 UPDATE KEP_CUSTOMER_RFQ B
                   SET B.CONTRACT_NOTE = #{st_con_note}
					 ,B.CONTRACT_IMAGE_KEY = #{st_image_key}
					 ,B.CONTRACT_ADD_DATE = SYSDATE
					 ,B.CONTRACT_ADD_USER_ID = #{USER_ID}
                 WHERE BUYER =#{st_com_code}
                 AND REVISION=#{st_revision}
